import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { toast } from '../libs/toast';
import './PosterView.css';
import Logo from '../components/Logo';

const PosterView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [announcement, setAnnouncement] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAnnouncement();
  }, [id]);

  const fetchAnnouncement = async () => {
    try {
      const response = await axios.get(`/api/announcements/${id}`);
      setAnnouncement(response.data);
    } catch (error) {
      toast.error('خطا در بارگیری اطلاعات آفیش');
      console.error('Error fetching announcement:', error);
    } finally {
      setLoading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = async () => {
    try {
      const element = document.getElementById('poster-content');
      if (element) {
        const html2canvas = (await import('html2canvas')).default;
        const canvas = await html2canvas(element, {
          scale: 2,
          useCORS: true,
          allowTaint: true
        });

        const link = document.createElement('a');
        link.download = `poster-${announcement?.id || 'announcement'}.png`;
        link.href = canvas.toDataURL();
        link.click();
      }
    } catch (error) {
      toast.error('خطا در دانلود پوستر');
      console.error('Error downloading poster:', error);
    }
  };

  if (loading) {
    return (
      <div className="poster-view-loading">
        <div className="spinner"></div>
        <p>در حال بارگیری...</p>
      </div>
    );
  }

  if (!announcement) {
    return (
      <div className="poster-view-error">
        <p>آفیش مورد نظر یافت نشد</p>
        <button onClick={() => navigate('/')} className="btn btn-primary">
          بازگشت به خانه
        </button>
      </div>
    );
  }

  return (
    <div className="poster-view-container">
      <div className="print-logo" aria-hidden="true">
        <Logo src="/logo.png.jpg" height={144} width={144} alt="لوگو" />
      </div>
      <div className="poster-actions">
        <button onClick={() => navigate(-1)} className="btn btn-secondary">
          بازگشت
        </button>
        <div className="action-buttons">
          <button onClick={handlePrint} className="btn btn-print">
            چاپ
          </button>
          <button onClick={handleDownload} className="btn btn-download">
            دانلود
          </button>
        </div>
      </div>

      <div id="poster-content" className="poster-content">
        <div className="poster-header">
          <h1>{announcement.title}</h1>
          <div className="announcement-meta">
            <span className="announcement-date">
              {new Date(announcement.date).toLocaleDateString('fa-IR')}
            </span>
            <span className="announcement-time">
              ساعت {announcement.time}
            </span>
          </div>
        </div>

        <div className="poster-body">
          {announcement.poster_image && (
            <div className="poster-image">
              <img
                src={announcement.poster_image.startsWith('http') ? announcement.poster_image : `/uploads/${announcement.poster_image}`}
                alt={announcement.title}
                crossOrigin="anonymous"
              />
            </div>
          )}

          <div className="announcement-details">
            <div className="detail-section">
              <h3>توضیحات</h3>
              <p>{announcement.description}</p>
            </div>

            {announcement.actors && announcement.actors.length > 0 && (
              <div className="detail-section">
                <h3>عوامل</h3>
                <div className="actors-list">
                  {announcement.actors.map((actor: any) => (
                    <div key={actor.id} className="actor-item">
                      {actor.name}
                      {actor.role_in_program && (
                        <span className="actor-role"> — {actor.role_in_program}</span>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {announcement.program_title && (
              <div className="detail-section">
                <h3>برنامه</h3>
                <div className="programs-list">
                  <div className="program-item">{announcement.program_title}</div>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="poster-footer">
          <p>سامانه رسا</p>
          <p className="poster-date">
            {new Date().toLocaleDateString('fa-IR')}
          </p>
        </div>
      </div>
    </div>
  );
};

export default PosterView;
